INSERT INTO `blogs` (`id`, `action_user`, `blog_categories_id`, `blog_title`, `blog_slug`, `blog_des`, `meta_des`, `thumbnailOne`, `thumbnailTwo`, `isPublished`, `created_at`, `updated_at`) VALUES
(6, 1, 4, 'Are You An Expert But Need Certification? Know More About RPL', 'are-you-an-expert-but-need-certification-know-more-about-rpl', '<p>\r\n\r\n</p><p class=\"MsoNormal\">The Recognition of prior learning (RPL) is recognised within\r\nthe Australian Qualifications Framework (AQF) as follows: Recognition of prior\r\nlearning is an assessment process that involves assessment of a person\'s\r\nrelevant prior learning (which includes formal, informal, and non-formal\r\nlearning) to work out the credit outcomes of a private application for credit.</p>\r\n\r\n<p class=\"MsoNormal\">The purpose of RPL is to spot, assess, recognise, and\r\nimprove a candidate\'s status in terms of what he/she knows and may do against\r\nnational standards and qualifications.</p>\r\n\r\n<p class=\"MsoNormal\">Recognition of Prior Learning (RPL) may be a process that\r\naccepts the talents that the scholar has gained through prior study (including\r\nformal, informal, and non-formal learning) or previous work experience or\r\nvolunteer work. If the candidate RPL a number of their units, the qualification\r\nthey\'re going to receive is not any different from the other.</p>\r\n\r\n<p class=\"MsoNormal\">To apply for the RPL candidate must submit an enquiry so\r\nthat the institution can provide an appropriate application form. The candidate\r\nneeds to submit their application before the start of the study. Along with\r\nthis form, the candidate must also need to supply any relevant documentation\r\nthat supports their application including existing qualifications and evidence\r\nof their previous roles. There\'s usually a fee that applies.</p>\r\n\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n\r\n<p class=\"MsoNormal\">It may be a method of assessment that considers whether a\r\nlearner can demonstrate that they will meet the assessment requirements for a\r\nunit or qualification through knowledge, understanding, or skills they already\r\npossess and don\'t got to develop through a course of learning. If a student\r\ndoesn\'t have a relevant qualification but feels that they\'ll already possess\r\nthe talents and knowledge that are defined by a specific unit of competency,\r\nthey may seek to possess these skills and knowledge recognised through a\r\nRecognition of Prior Learning (RPL) process.</p>\r\n\r\n<p class=\"MsoNormal\">Accordingly, in some circumstances, students could also be\r\nready to gain credit for a part of their training course supported the\r\nqualifications and/or statements of attainment that they already hold.</p>\r\n\r\n<p class=\"MsoNormal\">The RPL assessment process is as rigorous as the other\r\nassessment. However, the sort of evidence that a student must provide could\r\nalso be different from normal class assessments. Importantly though, the RPL\r\nprocess is flexible. The candidate and their RTO assessor will discuss and\r\ndetermine the evidence that they will provide.</p>\r\n\r\n<p class=\"MsoNormal\">There are four easy steps to get qualified!</p>\r\n\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n\r\n<p class=\"MsoNormal\"><b>FREE SKILLS TESTS CHECK:</b> A free, no-obligation, RPL\r\nskills check given by an experienced ITEC representative.</p>\r\n\r\n<p class=\"MsoNormal\"><b>EVIDENCE PORTFOLIO:</b> Compiling and submitting the\r\n\'Experience Portfolio\' to supply relevant documentation like photos and videos\r\nof the candidate on the work, references, previous qualifications, current\r\nresume, and so on.</p>\r\n\r\n<p class=\"MsoNormal\"><b>SKILLS CHECK:</b> a professional assessor, from one of\r\nour partnering RTOs, will review the evidence and determine if the individual\r\nis competent within the units for that qualification via an RPL assessment.</p>\r\n\r\n<p class=\"MsoNormal\"><b>QUALIFIED</b>: If the&nbsp;RTO&nbsp;assesses the\r\ncandidate as competent altogether required units of competency, then\r\nqualification is going to be awarded by the registered training organisation.</p>\r\n\r\n<p class=\"MsoNormal\">ITEC could be a workplace working with a variety of reputed\r\nInstitutes in Australia, which only refer students to Registered Training\r\nOrganisation and don\'t provide any certification. ITEC introduces students to\r\nEducube who assist students to enrol them and help them get a visa.</p><p><!--[if gte mso 9]><xml>\r\n <o:OfficeDocumentSettings>\r\n  <o:AllowPNG/>\r\n </o:OfficeDocumentSettings>\r\n</xml><![endif]--><!--[if gte mso 9]><xml>\r\n <w:WordDocument>\r\n  <w:View>Normal</w:View>\r\n  <w:Zoom>0</w:Zoom>\r\n  <w:TrackMoves/>\r\n  <w:TrackFormatting/>\r\n  <w:PunctuationKerning/>\r\n  <w:ValidateAgainstSchemas/>\r\n  <w:SaveIfXMLInvalid>false</w:SaveIfXMLInvalid>\r\n  <w:IgnoreMixedContent>false</w:IgnoreMixedContent>\r\n  <w:AlwaysShowPlaceholderText>false</w:AlwaysShowPlaceholderText>\r\n  <w:DoNotPromoteQF/>\r\n  <w:LidThemeOther>EN-US</w:LidThemeOther>\r\n  <w:LidThemeAsian>X-NONE</w:LidThemeAsian>\r\n  <w:LidThemeComplexScript>X-NONE</w:LidThemeComplexScript>\r\n  <w:Compatibility>\r\n   <w:BreakWrappedTables/>\r\n   <w:SnapToGridInCell/>\r\n   <w:WrapTextWithPunct/>\r\n   <w:UseAsianBreakRules/>\r\n   <w:DontGrowAutofit/>\r\n   <w:SplitPgBreakAndParaMark/>\r\n   <w:EnableOpenTypeKerning/>\r\n   <w:DontFlipMirrorIndents/>\r\n   <w:OverrideTableStyleHps/>\r\n  </w:Compatibility>\r\n  <m:mathPr>\r\n   <m:mathFont m:val=\"Cambria Math\"/>\r\n   <m:brkBin m:val=\"before\"/>\r\n   <m:brkBinSub m:val=\"&#45;-\"/>\r\n   <m:smallFrac m:val=\"off\"/>\r\n   <m:dispDef/>\r\n   <m:lMargin m:val=\"0\"/>\r\n   <m:rMargin m:val=\"0\"/>\r\n   <m:defJc m:val=\"centerGroup\"/>\r\n   <m:wrapIndent m:val=\"1440\"/>\r\n   <m:intLim m:val=\"subSup\"/>\r\n   <m:naryLim m:val=\"undOvr\"/>\r\n  </m:mathPr></w:WordDocument>\r\n</xml><![endif]--><!--[if gte mso 9]><xml>\r\n <w:LatentStyles DefLockedState=\"false\" DefUnhideWhenUsed=\"false\"\r\n  DefSemiHidden=\"false\" DefQFormat=\"false\" DefPriority=\"99\"\r\n  LatentStyleCount=\"376\">\r\n  <w:LsdException Locked=\"false\"